import time
import re
from .socketwrapper import RCISocket


class RCIConnection(object):
    """ Communicates with TMA application via RCI protocol.

    This class is an abstraction over RCI protocol. It enables sending commands
    and receiving responses to / from TMA application.

    Internally, this class uses two buffers: an internal one, for recently
    received responses, and a list, that stores messages that were taken out
    from the first in order to find the message the user is waiting for.

    In order to receive responses, first tell what response you are expecting
    to get by using one of wait_for_xyz methods. That method will then take all
    of the complete messages that are stored in the network buffer, and store
    them internally. Afterwards, it will look through the received messages one
    by one, take them out of the buffer, and put them in the responses list,
    until it finds what it was told to look for.

    The "parsed responses" list can be accessed by .responses attribute or via
    get_responses() method.

    Whenever a timeout parameter is taken, the accepted values are interpreted
    as follows:
        None - no timeout (indefinite)
        0 - non blocking - return as fast as possible, even if no message fits
            to what was requested
        any other float - raise an exception, if a fitting response wasn't
            found in the specified amount of seconds.

    In case of a float value, after a timeout the method will raise
    socket.timeout.
    """
    INDICATION_REGEX = r"I:.*"
    CONFIRMATION_REGEX = r"C:.*"

    def __init__(self, hostname, port):
        self._socket = RCISocket(hostname, port)
        self._connected = False
        self._response_buffer = []
        self._responses = []

    @property
    def responses(self):
        """ Return all already received responses. """
        return list(self._responses)

    def connect(self):
        """ Connect to the remote TMA application. """
        if self._connected:
            raise RCIConnectionError("already connected.")
        self._socket.connect()
        self._connected = True

    def disconnect(self):
        """ Disconnect from the TMA application.

        This will not reset the internal buffer of this object, nor the "parsed
        responses list", but it will reset the underlying socket. This means,
        that the already received messages will be remembered after
        disconnecting (e.g. if more than one was received when calling
        wait_for_next_response()), but if between the last "wait_for_xyz" call
        and disconnection a message was received, it will be lost.
        """
        if not self._connected:
            raise RCIConnectionError("not connected.")
        try:
            self._socket.disconnect()
        finally:
            self._connected = False

    @property
    def is_connected(self):
        return self._connected

    def send_command(self, command):
        """ Send a command to the TMA.

        The sent command doesn't have to end with CRLF - if the string lacks a
        proper ending, it will be added.
        """
        if not self._connected:
            raise RCIConnectionError("not connected.")
        self._socket.send_message(command)

    def get_responses(self):
        """ Return all of the "parsed responses", reset the response list. """
        responses = self._responses
        self._responses = []
        return responses

    def wait_for_next_response(self, timeout=None):
        """ Take the next received response into the response list, and return.

        If a response is already stored in an internal buffer (e.g. two
        responses were received the last time this method was called), this
        method will not try to receive any more responses from the remote.

        See class docstring for the definition of 'timeout' parameter.
        """
        if not self._response_buffer:
            if not self._connected:
                exc_msg = "no previously buffered messages and not connected."
                raise RCIConnectionError(exc_msg)
            self._response_buffer.extend(self._socket.recv_messages(timeout))
        if self._response_buffer:
            self._responses.append(self._response_buffer.pop(0))

    def wait_for_response(self, match, is_regex=False, timeout=None):
        """ Poll for the responses until a matching one is found.

        Has the same buffering semantics as wait_for_next_response().

        Arguments:
        match - pattern to match
        is_regex - (optional) if True, the pattern will be interpreted as a
            'pattern' in re.match(). Otherwise, it is taken as to be fully
            equal with expected response. False by default.

        See class docstring for the definition of 'timeout' parameter.
        """

        # TODO: replace with time.monotonic() after python2 compat is dropped
        start_time = time.time()
        remaining_time = timeout
        current_response = None

        while not self._matches(current_response, match, is_regex=is_regex):
            if timeout is not None:
                remaining_time = timeout - (time.time() - start_time)

            self.wait_for_next_response(remaining_time)
            current_response = self._responses[-1]

    @staticmethod
    def _matches(response, pattern, is_regex):
        if response is None:
            return False
        if not is_regex:
            return response == pattern
        else:
            return re.match(pattern, response) is not None

    def wait_for_next_indication(self, timeout=None):
        """ Poll for response until an indication is received.

        Interpretation of 'timeout' parameter and buffering semantics follow
        wait_for_next_response().
        """
        self.wait_for_response(self.INDICATION_REGEX, is_regex=True,
                               timeout=timeout)

    def wait_for_next_confirmation(self, timeout=None):
        """ Poll for response until a confirmation is received.

        Interpretation of 'timeout' parameter and buffering semantics follow
        wait_for_next_response().
        """
        self.wait_for_response(self.CONFIRMATION_REGEX, is_regex=True,
                               timeout=timeout)


class RCIConnectionError(Exception):
    """ Raised whenever RCIConnection is misused. """
